--
-- Name: stg_cleanAnswersDirtyData; Type: VIEW; Schema: scrape; Owner: postgres
--

CREATE VIEW scrape."stg_cleanAnswersDirtyData" AS
 SELECT number,
    question_number,
    question_exam,
    text,
    is_correct
   FROM scrape.answers
  WHERE (length(text) <> 0);


ALTER VIEW scrape."stg_cleanAnswersDirtyData" OWNER TO postgres;

--
-- Name: stg_findMissingAnswersLink; Type: VIEW; Schema: scrape; Owner: postgres
--

CREATE VIEW scrape."stg_findMissingAnswersLink" AS
 WITH missing_answers_link AS (
         SELECT DISTINCT answers.question_number
           FROM scrape.answers
          WHERE (length(answers.text) = 0)
        ), missing_answers AS (
         SELECT questionslink.number,
            questionslink.exam,
            questionslink.link
           FROM scrape.questionslink
          WHERE (questionslink.number IN ( SELECT missing_answers_link.question_number
                   FROM missing_answers_link))
        )
 SELECT number,
    exam,
    link
   FROM missing_answers
  WHERE (exam = '1z0-071'::text)
  ORDER BY number;


ALTER VIEW scrape."stg_findMissingAnswersLink" OWNER TO postgres;

--
-- Name: stg_relative_path_answers; Type: VIEW; Schema: scrape; Owner: postgres
--

CREATE VIEW scrape.stg_relative_path_answers AS
 WITH relative_path_answers AS (
         SELECT answers.number,
            answers.question_number,
            answers.question_exam,
            regexp_replace(answers.text, 'https?://[^/\s'']+/[^\s'']+/([^\s'']+\.[^\s'']+)'::text, '
![](../../images/\1)
		'::text, 'g'::text) AS text,
            answers.is_correct
           FROM scrape.answers
          WHERE (answers.question_exam = '1z0-071'::text)
        ), clean_assets AS (
         SELECT relative_path_answers.number,
            relative_path_answers.question_number,
            relative_path_answers.question_exam,
            regexp_replace(relative_path_answers.text, '/assets/media/[^ ]+/([^ /]+\.(?:png|jpg|jpeg|gif))'::text, '
![](../../images/\1)
		'::text, 'g'::text) AS text,
            relative_path_answers.is_correct
           FROM relative_path_answers
        ), clean_dirty_relative_path_answers AS (
         SELECT clean_assets.number,
            clean_assets.question_number,
            clean_assets.question_exam,
                CASE
                    WHEN (clean_assets.text ~~ '%pngMost%'::text) THEN replace(replace(clean_assets.text, 'pngMost'::text, 'png'::text), 'Voted'::text, ''::text)
                    ELSE clean_assets.text
                END AS text,
            clean_assets.is_correct
           FROM clean_assets
        )
 SELECT number,
    question_number,
    question_exam,
    text,
    is_correct
   FROM clean_dirty_relative_path_answers;


ALTER VIEW scrape.stg_relative_path_answers OWNER TO postgres;

