![](../../images/\1)
		'::text, 'g'::text) AS text
           FROM scrape.questions
          WHERE (questions.exam = '1z0-071'::text)
        ), clean_assets AS (
         SELECT relative_path_questions.number,
            relative_path_questions.exam,
            regexp_replace(relative_path_questions.text, '/assets/media/[^ ]+/([^ /]+\.(?:png|jpg|jpeg|gif))'::text, '
![](../../images/\1)
		'::text, 'g'::text) AS text
           FROM relative_path_questions
        )
 SELECT number,
    exam,
    text
   FROM clean_assets;


ALTER VIEW scrape.stg_relative_path_questions OWNER TO postgres;

--
-- Name: stg_viewAllImagesUrl; Type: VIEW; Schema: scrape; Owner: postgres
--

CREATE VIEW scrape."stg_viewAllImagesUrl" AS
 WITH image_url_questions AS (
         SELECT regexp_matches(questions.text, 'https?://[^/\s'']+/[^\s'']+\.[^\s'']+'::text, 'g'::text) AS url
           FROM scrape.questions
          WHERE (questions.exam = '1z0-071'::text)
        ), image_asset_questions AS (
         SELECT regexp_matches(questions.text, '/assets/media/[^ ]+/([^ /]+\.(?:png|jpg|jpeg|gif))'::text, 'g'::text) AS url
           FROM scrape.questions
          WHERE (questions.exam = '1z0-071'::text)
        ), image_url_answers AS (
         SELECT regexp_matches(answers.text, 'https?://[^/\s'']+/[^\s'']+\.[^\s'']+'::text, 'g'::text) AS url
           FROM scrape.answers
          WHERE (answers.question_exam = '1z0-071'::text)
        ), image_asset_answers AS (
         SELECT regexp_matches(answers.text, '/assets/media/[^ ]+/([^ /]+\.(?:png|jpg|jpeg|gif))'::text, 'g'::text) AS url
           FROM scrape.answers
          WHERE (answers.question_exam = '1z0-071'::text)
        ), all_image_url AS (
         SELECT unnest(image_url_questions.url) AS unnest
           FROM image_url_questions
        UNION
         SELECT ('https://www.examtopics.com/assets/media/exam-media/04351/'::text || unnest(image_asset_questions.url))
           FROM image_asset_questions
        UNION
         SELECT unnest(image_url_answers.url) AS unnest
           FROM image_url_answers
        UNION
         SELECT ('https://www.examtopics.com/assets/media/exam-media/04351/'::text || unnest(image_asset_answers.url))
           FROM image_asset_answers
  ORDER BY 1
        )
 SELECT dense_rank() OVER (ORDER BY unnest) AS number,
    unnest AS url
   FROM all_image_url
  ORDER BY unnest;


ALTER VIEW scrape."stg_viewAllImagesUrl" OWNER TO postgres;

