--
-- Name: cxpx_alo_ai1_report_high; Type: VIEW; Schema: raw; Owner: postgres
--

CREATE VIEW raw.cxpx_alo_ai1_report_high AS
 WITH base AS (
         SELECT stg_cxpc_alo_ai1.date_part,
            stg_cxpc_alo_ai1."High" AS high
           FROM raw.stg_cxpc_alo_ai1
          WHERE ((stg_cxpc_alo_ai1."Interval")::text = 'DAY_ONE'::text)
        ), max_date AS (
         SELECT max(stg_cxpc_alo_ai1.date_part) AS max_date_part
           FROM raw.stg_cxpc_alo_ai1
        ), begining_month_maximum_high AS (
         SELECT max(base.high) AS max_high,
            (date_trunc('month'::text, (max(max_date.max_date_part))::timestamp with time zone))::date AS start_date,
            max(max_date.max_date_part) AS end_date
           FROM (base
             JOIN max_date ON ((1 = 1)))
          WHERE ((base.date_part >= (date_trunc('month'::text, (max_date.max_date_part)::timestamp with time zone))::date) AND (base.date_part <= max_date.max_date_part))
        ), three_month_maximum_high AS (
         SELECT max(base.high) AS max_high,
            ((date_trunc('month'::text, (max(max_date.max_date_part))::timestamp with time zone) - '2 mons'::interval))::date AS start_date,
            max(max_date.max_date_part) AS end_date
           FROM (base
             JOIN max_date ON ((1 = 1)))
          WHERE ((base.date_part >= ((date_trunc('month'::text, (max_date.max_date_part)::timestamp with time zone) - '2 mons'::interval))::date) AND (base.date_part <= max_date.max_date_part))
        ), six_month_maximum_high AS (
         SELECT max(base.high) AS max_high,
            ((date_trunc('month'::text, (max(max_date.max_date_part))::timestamp with time zone) - '5 mons'::interval))::date AS start_date,
            max(max_date.max_date_part) AS end_date
           FROM (base
             JOIN max_date ON ((1 = 1)))
          WHERE ((base.date_part >= ((date_trunc('month'::text, (max_date.max_date_part)::timestamp with time zone) - '5 mons'::interval))::date) AND (base.date_part <= max_date.max_date_part))
        ), nine_month_maximum_high AS (
         SELECT max(base.high) AS max_high,
            ((date_trunc('month'::text, (max(max_date.max_date_part))::timestamp with time zone) - '8 mons'::interval))::date AS start_date,
            max(max_date.max_date_part) AS end_date
           FROM (base
             JOIN max_date ON ((1 = 1)))
          WHERE ((base.date_part >= ((date_trunc('month'::text, (max_date.max_date_part)::timestamp with time zone) - '8 mons'::interval))::date) AND (base.date_part <= max_date.max_date_part))
        ), twelve_month_maximum_high AS (
         SELECT max(base.high) AS max_high,
            ((date_trunc('month'::text, (max(max_date.max_date_part))::timestamp with time zone) - '11 mons'::interval))::date AS start_date,
            max(max_date.max_date_part) AS end_date
           FROM (base
             JOIN max_date ON ((1 = 1)))
          WHERE ((base.date_part >= ((date_trunc('month'::text, (max_date.max_date_part)::timestamp with time zone) - '11 mons'::interval))::date) AND (base.date_part <= max_date.max_date_part))
        ), entire_period_maximum_high AS (
         SELECT max(base.high) AS max_high,
            min(base.date_part) AS start_date,
            max(base.date_part) AS end_date
           FROM base
        ), onlyonerow AS (
         SELECT 'today period'::text AS period,
            base.high AS max_high,
            max_date.max_date_part AS start_date,
            max_date.max_date_part AS end_date
           FROM (base
             JOIN max_date ON ((1 = 1)))
          WHERE (base.date_part = max_date.max_date_part)
        )
 SELECT onlyonerow.period,
    onlyonerow.max_high,
    onlyonerow.start_date,
    onlyonerow.end_date
   FROM onlyonerow
UNION ALL
 SELECT '1st month period'::text AS period,
    begining_month_maximum_high.max_high,
    begining_month_maximum_high.start_date,
    begining_month_maximum_high.end_date
   FROM begining_month_maximum_high
UNION ALL
 SELECT '3rd month period'::text AS period,
    three_month_maximum_high.max_high,
    three_month_maximum_high.start_date,
    three_month_maximum_high.end_date
   FROM three_month_maximum_high
UNION ALL
 SELECT '6th month period'::text AS period,
    six_month_maximum_high.max_high,
    six_month_maximum_high.start_date,
    six_month_maximum_high.end_date
   FROM six_month_maximum_high
UNION ALL
 SELECT '9th month period'::text AS period,
    nine_month_maximum_high.max_high,
    nine_month_maximum_high.start_date,
    nine_month_maximum_high.end_date
   FROM nine_month_maximum_high
UNION ALL
 SELECT '12th month period'::text AS period,
    twelve_month_maximum_high.max_high,
    twelve_month_maximum_high.start_date,
    twelve_month_maximum_high.end_date
   FROM twelve_month_maximum_high
UNION ALL
 SELECT 'entire period'::text AS period,
    entire_period_maximum_high.max_high,
    entire_period_maximum_high.start_date,
    entire_period_maximum_high.end_date
   FROM entire_period_maximum_high;


