--
-- Name: sme_report; Type: VIEW; Schema: raw; Owner: postgres
--

CREATE VIEW raw.sme_report AS
 WITH aggregates AS (
         SELECT dim_report.prefix,
            dim_report.materialoutputquantity,
            dim_report.materialoutput,
            sum(dim_report.material_input_total_cost) AS material_input_total_cost,
            max(dim_report.material_output_total_sell_price) AS material_output_total_sell_price,
            max(dim_report.total_order_per_day) AS total_order_per_day
           FROM raw.dim_report
          WHERE ((dim_report.prefix = 'SME'::text) AND (dim_report.materialinput <> 'ALO'::text))
          GROUP BY dim_report.prefix, dim_report.materialoutputquantity, dim_report.materialoutput
        ), roiperday AS (
         SELECT aggregates.prefix,
            aggregates.materialoutputquantity,
            aggregates.materialoutput,
            ((aggregates.material_output_total_sell_price - aggregates.material_input_total_cost) * aggregates.total_order_per_day) AS roiperday
           FROM aggregates
        )
 SELECT prefix,
    materialoutputquantity,
    materialoutput,
    roiperday
   FROM roiperday
  ORDER BY roiperday DESC;


