--
-- Name: stg_recipe_inputs; Type: VIEW; Schema: raw; Owner: postgres
--

CREATE VIEW raw.stg_recipe_inputs AS
 WITH raw_data AS (
         SELECT recipe_inputs_raw."Key" AS raw_string
           FROM raw.recipe_inputs_raw
        ), unique_raw_data AS (
         SELECT DISTINCT raw_data.raw_string
           FROM raw_data
        ), parsed_prefix AS (
         SELECT unique_raw_data.raw_string AS original_query,
            split_part((unique_raw_data.raw_string)::text, ':'::text, 1) AS prefix,
            split_part((unique_raw_data.raw_string)::text, ':'::text, 2) AS recipe_string
           FROM unique_raw_data
        ), split_sides AS (
         SELECT parsed_prefix.original_query,
            parsed_prefix.prefix,
            split_part(parsed_prefix.recipe_string, '=>'::text, 1) AS input_str,
            split_part(parsed_prefix.recipe_string, '=>'::text, 2) AS output_str
           FROM parsed_prefix
        ), clean_data AS (
         SELECT split_sides.original_query,
            split_sides.prefix,
            ((regexp_matches(input_item.input_item, '(\d+)x([A-Z0-9]+)'::text))[1])::integer AS materialinputquantity,
            (regexp_matches(input_item.input_item, '(\d+)x([A-Z0-9]+)'::text))[2] AS materialinput,
            ((regexp_matches(split_sides.output_str, '(\d+)x([A-Z0-9]+)'::text))[1])::integer AS materialoutputquantity,
            (regexp_matches(split_sides.output_str, '(\d+)x([A-Z0-9]+)'::text))[2] AS materialoutput
           FROM split_sides,
            LATERAL unnest(string_to_array(split_sides.input_str, '-'::text)) input_item(input_item)
        )
 SELECT original_query,
    prefix,
    materialinputquantity,
    materialinput,
    materialoutputquantity,
    materialoutput
   FROM clean_data;


ALTER VIEW raw.stg_recipe_inputs OWNER TO postgres;

--
-- Name: stg_recipe_inputs_time; Type: VIEW; Schema: raw; Owner: postgres
--

CREATE VIEW raw.stg_recipe_inputs_time AS
 WITH raw_data AS (
         SELECT recipe_inputs_time_raw."Key" AS raw_string,
            recipe_inputs_time_raw."TimeMs" AS time_ms
           FROM raw.recipe_inputs_time_raw
        ), unique_raw_data AS (
         SELECT DISTINCT raw_data.raw_string,
            raw_data.time_ms
           FROM raw_data
        ), replace AS (
         SELECT replace((unique_raw_data.raw_string)::text, '#'::text, ':'::text) AS raw_string_one,
            unique_raw_data.time_ms
           FROM unique_raw_data
        ), replacetwo AS (
         SELECT replace(replace.raw_string_one, ' '::text, '-'::text) AS raw_string_two,
            replace.time_ms
           FROM replace
        ), parsed_prefix AS (
         SELECT replacetwo.raw_string_two AS original_query,
            split_part(replacetwo.raw_string_two, ':'::text, 1) AS prefix,
            split_part(replacetwo.raw_string_two, ':'::text, 2) AS recipe_string,
            replacetwo.time_ms
           FROM replacetwo
        ), split_sides AS (
         SELECT parsed_prefix.original_query,
            parsed_prefix.prefix,
            split_part(parsed_prefix.recipe_string, '=>'::text, 1) AS input_str,
            split_part(parsed_prefix.recipe_string, '=>'::text, 2) AS output_str,
            parsed_prefix.time_ms
           FROM parsed_prefix
        ), clean_data AS (
         SELECT split_sides.original_query,
            split_sides.prefix,
            ((regexp_matches(input_item.input_item, '(\d+)x([A-Z0-9]+)'::text))[1])::integer AS materialinputquantity,
            (regexp_matches(input_item.input_item, '(\d+)x([A-Z0-9]+)'::text))[2] AS materialinput,
            ((regexp_matches(split_sides.output_str, '(\d+)x([A-Z0-9]+)'::text))[1])::integer AS materialoutputquantity,
            (regexp_matches(split_sides.output_str, '(\d+)x([A-Z0-9]+)'::text))[2] AS materialoutput,
            split_sides.time_ms
           FROM split_sides,
            LATERAL unnest(string_to_array(split_sides.input_str, '-'::text)) input_item(input_item)
        )
 SELECT original_query,
    prefix,
    materialinputquantity,
